internal class UPSBasePriceCalcItem extends UPSBasePriceCalcBase
{
    private UPSItemBasePriceCalcTable   basePriceCalcTable;
    private UPSItemBasePriceCalcTrans   basePriceCalcTrans;

    private UPSBasePriceVersionId       basePriceVersionId;
    private UPSBasePriceVersion         basePriceVersion;

    private UPSBasePriceCalcPriceCalcId priceCalcId;
    private InventSiteId                siteId;
    private NoYes                       purchPriceTransfer;
    private NoYes                       salesPriceTransfer;
    private NoYes                       costPriceTransfer;
    private CurrencyCode                curCurrency;

    private RecordInsertList            itemBasePriceCalcTransDetailList;

    private UPSBasePriceRawData         basePriceRawData;
    private InventDim                   inventDimCriteriaForCalcItem;
    private InventDimParm               productDims;

}

Method.Source:
