public UPSBasePriceRawData parmBasePriceRawData(UPSBasePriceRawData _basePriceRawData)
{
    basePriceRawData = _basePriceRawData;

    return basePriceRawData;
}

public void calc()
{
    ListEnumerator  listEnumerator;

    try
    {
        setPrefix(UPSBasePriceCalcItem::description());

        if (inventDimId != InventDim::inventDimIdBlank())
        {
            setPrefix(strFmt("%1 (%2)", strFmt("@SYS24300", itemId), inventDim.preFixValue()));
        }
        else
        {
            setPrefix(strFmt("@SYS24300", itemId));
        }

        if (!this.validate())
        {
            throw Exception::Error;
        }

        if (!this.existingVendPriceList(this.key1(), this.parmSiteId()))
        {
            return;
        }

        this.init();

        this.setProgressTotals();

        this.recalcBasePrice();

        this.insertBasePriceCalcTable();
    }
    catch (Exception::Error)
    {
        throw error("@SYS19457");
    }

}

void recalcBasePrice()
{
    this.setLineNum();

    this.updateProgress();

    this.calcPriceForPriceType();

    this.markFinalPrice();

    this.insertBasePriceCalcTrans();

    this.deleteTransDetails();
}

private void deleteTransDetails()
{
    UPSItemBasePriceCalcTransDetail calcTransDetail;
    delete_from calcTransDetail where calcTransDetail.PriceCalcId == priceCalcId;
}

public void init()
{
    this.initParameters();

    itemBasePriceCalcTransDetailList = new RecordInsertList(tableNum(UPSItemBasePriceCalcTransDetail));

    basePriceVersion = UPSBasePriceVersion::find(basePriceVersionId);

    inventDimCriteriaForCalcItem = this.parmInventDim();
    productDims.initFromInventDim(inventDimCriteriaForCalcItem, InventDim::dimProductDimFieldList());
}

protected void initParameters()
{
    NumberSeq   numberSeq;

    super();

    if (!priceCalcId)
    {
        if (basePriceCalcTable.PriceCalcId)
        {
            priceCalcId = basePriceCalcTable.PriceCalcId;
        }
        else
        {
            numberSeq   = NumberSeq::newGetNum(BOMParameters::numRefPriceCalcId());
            priceCalcId = numberSeq.num();
        }
    }

    curCurrency = Ledger::accountingCurrency(CompanyInfo::current());

    this.initProgressBar();
    this.incProgressTotals();
}

boolean existingVendPriceList(
    ItemId                          _itemId,
    InventSiteId                    _inventSiteId)
{
    UPSVendListPriceView    vendListPrices;

    InventDim       inventDimSite;
    InventDim       inventDimCriteria;
    InventDimParm   inventDimParm;

    inventDimCriteria.InventSiteId  = _inventSiteId;
    inventDimParm.inventSiteIdFlag  = NoYes::Yes;

    select firstonly vendListPrices
        where vendListPrices.ItemNum == _itemId
        #InventDimJoin(vendListPrices.inventDimId, inventDimSite, inventDimCriteria, inventDimParm);

    return vendListPrices.RecId;
}

void calcPriceForPriceType()
{
    UPSVendListPriceTmp     vendListPriceTmp;
    InventDim               inventDimCalcItem;

    vendListPriceTmp = basePriceRawData.paramVendListPriceTmp();

    // Per item calculation task, we only have site and product variants dimensions if necessary
    while select vendListPriceTmp
        order by vendListPriceTmp.AccountCode, vendListPriceTmp.AccountNum
        where  vendListPriceTmp.ItemId == this.key1()
        #InventDimExistsJoin(vendListPriceTmp.InventDimId, inventDimCalcItem, inventDimCriteriaForCalcItem, productDims)
    {
        if (this.parmPurchPriceTransfer())
        {
            this.calcTmpBasePricePerPriceType(vendListPriceTmp, UPSBasePriceType::BasePricePurchase);
        }

        if (this.parmSalesPriceTransfer())
        {
            this.calcTmpBasePricePerPriceType(vendListPriceTmp, UPSBasePriceType::BasePriceSales);
        }

        if (this.parmCostPriceTransfer())
        {
            this.calcTmpBasePricePerPriceType(vendListPriceTmp, UPSBasePriceType::BasePriceInventoryCost);
        }
    }

    itemBasePriceCalcTransDetailList.insertDatabase();
}

void calcTmpBasePricePerPriceType(UPSVendListPriceTmp _vendListPriceTmp, UPSBasePriceType _basePriceType)
{
    UPSPriceTermAgreementTmp            priceTermAgreementTmp;
    UPSItemBasePriceCalcTransDetail     itemBasePriceCalcTransDetail;

    UPSVendListPriceAndPriceTermAgreementTmp vendListPriceAndPriceTermsTmp;

    InventDim       priceTermInventDim;
    InventDim       vendListPriceDim;

    UPSVendPriceAmount          defaultPrice;
    UPSBaseAmountNonMonetary    calculatedValue;
    UPSBaseAmountNonMonetary    calculatedPrice;
    LineNum                     calcTransLineNum;

    PriceConvertFactory         priceConvertFactory;
    PriceConvert                priceConvert;
    CurrencyCode                transCurrency;

    vendListPriceDim = InventDim::find(_vendListPriceTmp.InventDimId);

    priceTermAgreementTmp = basePriceRawData.paramPriceTermAgreementTmp();
    vendListPriceAndPriceTermsTmp = basePriceRawData.paramVendListPriceAndPriceTermAgreementTmp();

    defaultPrice        = _vendListPriceTmp.Amount;
    transCurrency       = _vendListPriceTmp.Currency;

    priceConvertFactory = PriceConvertFactory::newItemPrice(_vendListPriceTmp.ItemId,
                                                            _vendListPriceTmp.UnitId,
                                                             defaultPrice,
                                                             _vendListPriceTmp.PriceUnit,
                                                             _vendListPriceTmp.Markup,
                                                             1,
                                                             transCurrency);

    priceConvertFactory.parmNewCurrencyCode(curCurrency);
    priceConvertFactory.parmNewUnitId(this.getNewUnitId(_vendListPriceTmp.ItemId, _basePriceType));
    priceConvert = priceConvertFactory.priceConvert();
    defaultPrice = priceConvert.parmPrice();

    calculatedPrice = defaultPrice;
    calcTransLineNum = 1;
    // TODO: Just consider the product dimensions and storage dimensions
    while select priceTermAgreementTmp
        order by priceTermAgreementTmp.CalculationSequence
        join vendListPriceAndPriceTermsTmp
        where vendListPriceAndPriceTermsTmp.PriceTermAgreementTmpRecId == priceTermAgreementTmp.RecId
           && vendListPriceAndPriceTermsTmp.VendListPriceTmpRecId == _vendListPriceTmp.RecId
           && ((_basePriceType ==UPSBasePriceType ::BasePricePurchase && priceTermAgreementTmp.CalculateBasePricePurchase == NoYes::Yes)   ||
               (_basePriceType ==UPSBasePriceType ::BasePriceSales && priceTermAgreementTmp.CalculateBasePriceSales == NoYes::Yes)         ||
               (_basePriceType ==UPSBasePriceType ::BasePriceInventoryCost && priceTermAgreementTmp.CalculateBasePriceInventory == NoYes::Yes)) 
        /*join priceTermInventDim
        where priceTermInventDim.inventDimId == priceTermAgreementTmp.InventDimId
            && (priceTermInventDim.InventSiteId == vendListPriceDim.InventSiteId)
            && (priceTermInventDim.InventSizeId == vendListPriceDim.InventSizeId || !vendListPriceDim.InventSizeId || !priceTermInventDim.InventSizeId)
            && (priceTermInventDim.InventColorId == vendListPriceDim.InventColorId || !vendListPriceDim.InventColorId || !priceTermInventDim.InventColorId)
            && (priceTermInventDim.InventStyleId == vendListPriceDim.InventStyleId || !vendListPriceDim.InventStyleId || !priceTermInventDim.InventStyleId)
            && (priceTermInventDim.configId == vendListPriceDim.configId || !vendListPriceDim.configId || !priceTermInventDim.configId)
            && (priceTermInventDim.InventLocationId == vendListPriceDim.InventLocationId || !vendListPriceDim.InventLocationId || !priceTermInventDim.InventLocationId)*/
    {
        itemBasePriceCalcTransDetail.clear();

        if (priceTermAgreementTmp.CalculateMethod == UPSPriceTermCalculateMethod::FixedAmount)
        {
            calculatedValue = priceTermAgreementTmp.Value;
            priceConvertFactory.parmUnitId(priceTermAgreementTmp.UnitId);
            priceConvertFactory.parmPrice(calculatedValue);
            priceConvert    = priceConvertFactory.priceConvert();
            calculatedValue = priceConvert.parmPrice();
        }
        else if (priceTermAgreementTmp.CalculateMethod == UPSPriceTermCalculateMethod::Percent)
        {
            if (priceTermAgreementTmp.CompoundCalculationBasis)
            {
                calculatedValue = calculatedPrice * priceTermAgreementTmp.Value/100;
            }
            else
            {
                calculatedValue = defaultPrice * priceTermAgreementTmp.Value/100;
            }
        }

        calculatedPrice =  calculatedPrice + calculatedValue;

        if (priceTermAgreementTmp.CompoundCalculationBasis && priceTermAgreementTmp.CalculateMethod == UPSPriceTermCalculateMethod::Percent)
        {
            itemBasePriceCalcTransDetail.BasePrice         = calculatedPrice - calculatedValue;
        }
        else
        {
            itemBasePriceCalcTransDetail.BasePrice         = defaultPrice;
        }

        itemBasePriceCalcTransDetail.PriceCalcId       = priceCalcId;
        itemBasePriceCalcTransDetail.LineNum           = calcTransLineNum;
        itemBasePriceCalcTransDetail.PriceType         = _basePriceType;
        itemBasePriceCalcTransDetail.AccountCode       = _vendListPriceTmp.AccountCode;
        itemBasePriceCalcTransDetail.AccountRelation   = _vendListPriceTmp.AccountNum;
        itemBasePriceCalcTransDetail.CalculateMethod   = priceTermAgreementTmp.CalculateMethod;
        itemBasePriceCalcTransDetail.PriceTerm         = priceTermAgreementTmp.Code;
        itemBasePriceCalcTransDetail.Value             = priceTermAgreementTmp.Value;
        itemBasePriceCalcTransDetail.CalculatedValue   = calculatedValue;
        itemBasePriceCalcTransDetail.CalculatedPrice   = calculatedPrice;

        itemBasePriceCalcTransDetail.CompoundCalculationBasis = priceTermAgreementTmp.CompoundCalculationBasis;

        calcTransLineNum++;
        itemBasePriceCalcTransDetailList.add(itemBasePriceCalcTransDetail);
    }
}

private UnitOfMeasureSymbol getNewUnitId(ItemId _itemId, UPSBasePriceType _priceType)
{
    UnitOfMeasureSymbol     unitOfMeasureSymbol;
    InventTable             inventTable = InventTable::find(_itemId);

    switch (_priceType)
    {
        case UPSBasePriceType::BasePriceInventoryCost :
            unitOfMeasureSymbol = inventTable.inventUnitId();
            break;

        case UPSBasePriceType::BasePricePurchase :
            unitOfMeasureSymbol = inventTable.purchUnitId();
            break;

        case UPSBasePriceType::BasePriceSales :
            unitOfMeasureSymbol = inventTable.salesUnitId();
            break;
    }

    return unitOfMeasureSymbol;
}

static UPSBasePriceCalcItem newItem(
    UPSBasePriceRawData             _basePriceRawData,
    ItemId                          _itemId,
    InventDimId                     _inventDimId,
    UPSBasePriceCalcPriceCalcId     _priceCalcId              = '',
    TransDate                       _calcDate                 = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
    UPSBasePriceVersionId           _basePriceVersionId       = '',
    UPSCalcBasePriceVersionUpdate   _calcVersionUpdate        = UPSCalcBasePriceVersionUpdate::Overwrite,
    NoYes                           _purchPriceTransfer       = NoYes::No,
    NoYes                           _salesPriceTransfer       = NoYes::No,
    NoYes                           _costPriceTransfer        = NoYes::No)
{
    UPSBasePriceCalcItem basePriceCalcItem;
    InventDim       foundInventDim;

    basePriceCalcItem = UPSBasePriceCalcItem::construct();

    basePriceCalcItem.parmBasePriceRawData(_basePriceRawData);

    basePriceCalcItem.parmItemId(_itemId);

    foundInventDim = InventDim::find(_inventDimId);
    basePriceCalcItem.parmInventDimId(_inventDimId);
    basePriceCalcItem.parmInventDim(foundInventDim);

    if (foundInventDim)
    {
        basePriceCalcItem.parmSiteId(foundInventDim.InventSiteId);
    }

    basePriceCalcItem.parmPriceCalcId(_priceCalcId);
    basePriceCalcItem.parmCalcDate(_calcDate);
    basePriceCalcItem.parmBasePriceVersionId(_basePriceVersionId);
    basePriceCalcItem.parmPurchPriceTransfer(_purchPriceTransfer);
    basePriceCalcItem.parmSalesPriceTransfer(_salesPriceTransfer);
    basePriceCalcItem.parmCostPriceTransfer(_costPriceTransfer);

    return basePriceCalcItem;
}

static UPSBasePriceCalcItem construct()
{
    return new UPSBasePriceCalcItem();
}

static ClassDescription description()
{
    return "@SYS5681";
}

protected void initializeBasePriceCalcTable()
{
    basePriceCalcTable.ItemId           = this.key1();
    basePriceCalcTable.InventDimId      = this.key2();
    basePriceCalcTable.PriceCalcId      = priceCalcId;
    basePriceCalcTable.UnitId           = inventUnitId;
    basePriceCalcTable.VersionId        = basePriceVersionId;
    basePriceCalcTable.Currency         = curCurrency;
    basePriceCalcTable.PriceRule        = basePriceVersion.PriceRule;
    basePriceCalcTable.PriceBasis       = basePriceVersion.PriceBasis;
}

public void insertBasePriceCalcTable()
{
    this.initializeBasePriceCalcTable();

    if (basePriceCalcTable.RecId)
    {
        basePriceCalcTable.update();
    }
    else
    {
        basePriceCalcTable.insert();
    }
}

public void insertBasePriceCalcTrans() { UPSItemBasePriceCalcTransDetail itemBasePriceCalcTransDetailLocal; UPSItemBasePriceCalcTransDetail theCheapPriceResult;
UPSItemBasePriceCalcTrans itemBasePriceCalcTrans;
while select minof(CalculatedPrice) from itemBasePriceCalcTransDetailLocal group by PriceType where itemBasePriceCalcTransDetailLocal.FinalPrice == NoYes::Yes && itemBasePriceCalcTransDetailLocal.PriceCalcId == priceCalcId { UPSItemBasePriceCalcTransDetail itemBasePriceCalcTransDetail = UPSItemBasePriceCalcTransDetail::findByFinalPrice( itemBasePriceCalcTransDetailLocal.PriceType, itemBasePriceCalcTransDetailLocal.CalculatedPrice, priceCalcId);
insert_recordset itemBasePriceCalcTrans ( AccountCode, AccountRelation, PriceCalcId, PriceType, PriceTerm, BasePrice, CalculateMethod, Value, CalculatedValue, CalculatedPrice, CompoundCalculationBasis, FinalPrice) select AccountCode, AccountRelation, PriceCalcId, PriceType, PriceTerm, BasePrice, CalculateMethod, Value, CalculatedValue, CalculatedPrice, CompoundCalculationBasis, FinalPrice from theCheapPriceResult where theCheapPriceResult.AccountCode == itemBasePriceCalcTransDetail.AccountCode && theCheapPriceResult.AccountRelation == itemBasePriceCalcTransDetail.AccountRelation && theCheapPriceResult.PriceType == itemBasePriceCalcTransDetail.PriceType; } }

void markFinalPrice()
{
    UPSItemBasePriceCalcTransDetail itemBasePriceCalcTransDetailLocal;

    ttsbegin;

     while select maxof(LineNum) from itemBasePriceCalcTransDetailLocal
        group by PriceType, AccountCode, AccountRelation
        where itemBasePriceCalcTransDetailLocal.PriceCalcId == priceCalcId
    {
        UPSItemBasePriceCalcTransDetail itemBasePriceCalcTransDetail;

        itemBasePriceCalcTransDetail = UPSItemBasePriceCalcTransDetail::findByLineNum(
            itemBasePriceCalcTransDetailLocal.PriceType,
            itemBasePriceCalcTransDetailLocal.AccountCode,
            itemBasePriceCalcTransDetailLocal.AccountRelation,
            itemBasePriceCalcTransDetailLocal.LineNum,
            priceCalcId,
            true);

        itemBasePriceCalcTransDetail.FinalPrice = NoYes::Yes;
        itemBasePriceCalcTransDetail.doUpdate();
    }

    ttscommit;
}

protected KeyValue key1()
{
    return itemId;
}

protected KeyValue key2()
{
    return inventDimId;
}

UPSItemBasePriceCalcTable parmBasePriceCalcTable(UPSItemBasePriceCalcTable _basePriceCalcTable = basePriceCalcTable)
{
    basePriceCalcTable = _basePriceCalcTable;
    return basePriceCalcTable;
}

UPSItemBasePriceCalcTrans parmBasePriceCalcTrans(UPSItemBasePriceCalcTrans _basePriceCalcTrans= basePriceCalcTrans)
{
    basePriceCalcTrans = _basePriceCalcTrans;
    return basePriceCalcTrans;
}
